export type PostStatus = 'Draft' | 'Published' | 'Scheduled';

export interface JournalPost {
    id: string;
    title: string;
    content: string;
    status: PostStatus;
    createdAt: string;
}

const initialPosts: JournalPost[] = [
    {
        id: 'post-1',
        title: 'Field Notes: Building a resilient workflow',
        content: 'A short note about how the journal workflow evolved from rough sketches into a repeatable publication cadence.',
        status: 'Published',
        createdAt: '2026-08-11',
    },
    {
        id: 'post-2',
        title: 'Prototype review and iteration loop',
        content: 'A draft capturing the cycle of prototyping, feedback, and refinement that shaped the current release.',
        status: 'Draft',
        createdAt: '2026-08-12',
    },
];

let posts: JournalPost[] = [...initialPosts];

export function getPosts(): JournalPost[] {
    return posts;
}

export function createPost(input: { title: string; content: string; status?: PostStatus }) {
    const newPost: JournalPost = {
        id: `post-${Date.now()}`,
        title: input.title.trim(),
        content: input.content.trim(),
        status: input.status ?? 'Draft',
        createdAt: new Date().toISOString().slice(0, 10),
    };

    posts = [newPost, ...posts];
    return newPost;
}
